function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'LogSystem' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with LogSystem and no arguments.';
  if (operations.length - 1 > 500) return 'At most 500 calls to put and retrieve.';
  const units = ['Year', 'Month', 'Day', 'Hour', 'Minute', 'Second'];
  const limits = [[2000, 2017], [1, 12], [1, 31], [0, 23], [0, 59], [0, 59]];
  const validStamp = text => typeof text === 'string' && /^\d{4}(:\d{2}){5}$/.test(text) && text.split(':').every((part, i) => +part >= limits[i][0] && +part <= limits[i][1]);
  const ids = new Set();
  for (let i = 1; i < operations.length; i++) {
    const params = args[i];
    if (!Array.isArray(params)) return 'Each call needs a list of arguments.';
    if (operations[i] === 'put') {
      const [id, timestamp] = params;
      if (params.length !== 2 || !Number.isInteger(id) || id < 1 || id > 500) return 'put takes an id from 1 to 500 and a timestamp.';
      if (ids.has(id)) return 'Every log needs a different id.';
      ids.add(id);
      if (!validStamp(timestamp)) return 'Timestamps look like "2017:01:01:23:59:59" with fields in range.';
    } else if (operations[i] === 'retrieve') {
      const [start, end, granularity] = params;
      if (params.length !== 3 || !validStamp(start) || !validStamp(end)) return 'retrieve takes two valid timestamps and a granularity.';
      if (!units.includes(granularity)) return 'granularity is Year, Month, Day, Hour, Minute or Second.';
    } else return 'Only put and retrieve can follow the constructor.';
  }
  return null;
}

