class LogSystem {
  constructor() {
    this.logs = [];
    this.prefixLength = new Map([
      ['Year', 4],
      ['Month', 7],
      ['Day', 10],
      ['Hour', 13],
      ['Minute', 16],
      ['Second', 19],
    ]);
  }

  put(id, timestamp) {
    this.logs.push([id, timestamp]);
  }

  retrieve(start, end, granularity) {
    const length = this.prefixLength.get(granularity);
    const low = start.slice(0, length);
    const high = end.slice(0, length);
    const result = [];
    for (const [id, timestamp] of this.logs) {
      const key = timestamp.slice(0, length);
      if (key >= low && key <= high) {
        result.push(id);
      }
    }
    return result;
  }
}

