class LogSystem {
  constructor() {
    this.entries = [];
  }
  put(id, timestamp) {
    this.entries.push({ id, timestamp });
  }
  retrieve(start, end, granularity) {
    const keep = ['Year', 'Month', 'Day', 'Hour', 'Minute', 'Second'].indexOf(granularity) + 1;
    // Fields past the granularity become 0 for the lower bound and 99 for the upper bound.
    const encode = (text, count, fill) => text.split(':').map(Number).reduce((total, part, i) => total * 100 + (i < count ? part : fill), 0);
    const lowest = encode(start, keep, 0);
    const highest = encode(end, keep, 99);
    return this.entries.filter(entry => {
      const moment = encode(entry.timestamp, 6, 0);
      return moment >= lowest && moment <= highest;
    }).map(entry => entry.id);
  }
}

