function generate(rand, size) {
  const pad = (value, width) => String(value).padStart(width, '0');
  const between = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const choose = list => list[Math.floor(rand() * list.length)];
  const units = ['Year', 'Month', 'Day', 'Hour', 'Minute', 'Second'];
  // Small (and some large) inputs reuse a few values per field so that ranges hit their edges.
  const tight = size === 'small' || rand() < 0.3;
  const stamp = () => {
    const fields = tight
      ? [choose([2000, 2016, 2017]), choose([1, 2, 12]), choose([1, 2, 31]), choose([0, 1, 23]), choose([0, 1, 59]), choose([0, 1, 59])]
      : [between(2000, 2017), between(1, 12), between(1, 31), between(0, 23), between(0, 59), between(0, 59)];
    return fields.map((value, i) => pad(value, i === 0 ? 4 : 2)).join(':');
  };
  const ids = Array.from({ length: 500 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [ids[i], ids[j]] = [ids[j], ids[i]];
  }
  const operations = ['LogSystem'];
  const args = [[]];
  const stored = [];
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 12);
  const putRate = 0.4 + rand() * 0.4;
  for (let i = 0; i < calls; i++) {
    if (rand() < putRate) {
      const timestamp = stored.length > 0 && rand() < 0.15 ? choose(stored) : stamp();
      stored.push(timestamp);
      operations.push('put');
      args.push([ids.pop(), timestamp]);
      continue;
    }
    let start = stored.length > 0 && rand() < 0.4 ? choose(stored) : stamp();
    let end = stored.length > 0 && rand() < 0.4 ? choose(stored) : stamp();
    if (start > end && rand() < 0.8) [start, end] = [end, start];
    operations.push('retrieve');
    args.push([start, end, choose(units)]);
  }
  return [operations, args];
}
